{"path": "tax.py", "content": "from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal("0.01")


def _dec(value):
    # Go through str() so binary float noise (e.g. 1.25 * 0.1) doesn't skew rounding.
    return value if isinstance(value, Decimal) else Decimal(str(value))


def line_tax_decimal(price, rate):
    """Tax for one line, rounded half-up to whole cents, as a Decimal."""
    return (_dec(price) * _dec(rate)).quantize(CENT, rounding=ROUND_HALF_UP)


def line_tax(price, rate):
    """Tax for one line, rounded half-up to whole cents (0.125 -> 0.13)."""
    return float(line_tax_decimal(price, rate))
